UPDATE reconciliation_file_batch SET status = #{status}, completed_at = #{completedAt},
    failure_reason = #{failureReason}, updated_at = CURRENT_TIMESTAMP
WHERE file_id = #{fileId} AND status = #{expectedStatus}

UPDATE reconciliation_file_batch SET status = #{row.status}, actual_record_count = #{row.actualRecordCount},
    failure_reason = #{row.failureReason}, updated_at = #{row.updatedAt}, completed_at = #{row.completedAt}
WHERE file_id = #{row.fileId} AND status = #{expectedStatus} AND updated_at = #{expectedUpdatedAt}
